#!/usr/bin/env node
// PreToolUse (Edit|Write): block edits to secrets, applied migrations, lockfiles and generated files.
import { existsSync } from "node:fs";
import { basename } from "node:path";

const input = JSON.parse(await readStdin());
const filePath = input.tool_input?.file_path ?? "";
const normalized = filePath.replace(/\\/g, "/");
const name = basename(normalized);

const blockers = [
  {
    test: () => /(^|\/)\.env(\..+)?$/.test(normalized) && name !== ".env.example",
    reason: "Refusing to edit a real .env file. Edit .env.example instead.",
  },
  {
    test: () => /\/packages\/db\/migrations\/.+\.sql$/.test(normalized) && existsSync(filePath),
    reason: "Refusing to edit an existing migration file. Generate a new migration instead.",
  },
  {
    test: () => name === "pnpm-lock.yaml",
    reason: "Refusing to hand-edit pnpm-lock.yaml. Run pnpm install to change it.",
  },
  {
    test: () => name === "next-env.d.ts",
    reason: "Refusing to edit next-env.d.ts — it is generated by Next.js.",
  },
  {
    test: () => /\.gen\.ts$/.test(name),
    reason: "Refusing to edit a generated *.gen.ts file.",
  },
];

for (const blocker of blockers) {
  if (blocker.test()) {
    console.error(blocker.reason);
    process.exit(2);
  }
}

function readStdin() {
  return new Promise((resolve) => {
    let data = "";
    process.stdin.on("data", (chunk) => (data += chunk));
    process.stdin.on("end", () => resolve(data));
  });
}
